import test from 'node:test';
import assert from 'node:assert/strict';
import {treeProfile} from '../scenic-trees.js';
import {regionalCraftKind,drawRegional} from '../regional-art.js';
import {civilianStance,drawCivilian,civilianPalette} from '../npc-art.js';
import {villagePose,drawVillageLife} from '../village-life-art.js';
import {REGIONS} from '../regional-content.js';
function context(){const calls=[],gradient={addColorStop(){}};const c=new Proxy({globalAlpha:1},{get(o,k){if(k in o)return o[k];if(k==='createLinearGradient'||k==='createRadialGradient')return()=>gradient;return(...a)=>calls.push([k,...a]);},set(o,k,v){o[k]=v;return true;}});return{c,calls};}
test('regional craft silhouettes show each of the 24 actual material practices',()=>{assert.equal(new Set(REGIONS.map(regionalCraftKind)).size,24);const before=JSON.stringify(REGIONS);for(const p of REGIONS)for(const lifeKind of ['project','herb','fauna']){const {c,calls}=context();drawRegional(c,{profile:p,lifeKind,xy:[2,4]},2,{townLife:{minutes:0},regionalLife:{projects:[p.chapter]}});assert.ok(calls.length>10);assert.ok(calls.every(a=>a.slice(1).filter(x=>typeof x==='number').every(Number.isFinite)));}assert.equal(JSON.stringify(REGIONS),before);});
test('tree families keep stable proportions and deterministic varied silhouettes',()=>{const profiles=Array.from({length:24},(_,i)=>treeProfile(i*7297+431));assert.ok(new Set(profiles.map(p=>p.height)).size>20);for(const p of profiles){assert.ok(p.height>=140&&p.height<=194);assert.ok(p.width>=134&&p.width<=176);assert.deepEqual(p,treeProfile(p.seed));}assert.equal(treeProfile(10,'highland').pine,true);assert.equal(treeProfile(10,'mangrove').willow,true);});
test('civilian stance and animal poses never lift their entire root off the floor',()=>{const o={name:'Alba',lifeKind:'cat',path:[[4,5]],facing:1,xy:[2,3]},state={mode:'field',x:10,y:10};for(const t of [0,.2,1,2]){const {c,calls}=context();drawCivilian({ctx:c,assets:{npcs:{}},atlas(...a){calls.push(['atlas',...a]);}},o,{name:'Alba'},2.5,3.5,t,state);assert.deepEqual(calls.find(a=>a[0]==='translate').slice(1),[120,168]);assert.ok(Math.abs(civilianStance(o,t,state,2.5,3.5).lean)<=.012);const b=context();drawVillageLife(b.c,o,t,{});assert.deepEqual(b.calls.find(a=>a[0]==='translate').slice(1),[120,168]);}for(const t of [undefined,NaN,Infinity,-100])assert.ok(Number.isInteger(villagePose(o,t)));});

test('named civilians retain authored clothes while neighboring households have stable varied dyes',()=>{for(const name of ['Mara','Nell','Father','Dara','Hesper','Corin'])assert.equal(civilianPalette({name},{name}),0);const colors=['Tomas','Elsa','Seth','Nola','Len','Esme','Ada','Oren','Fara','Yun'].map(name=>civilianPalette({name},{name}));assert.ok(new Set(colors).size>=5);assert.equal(civilianPalette({name:'Elsa'},{name:'Elsa'}),civilianPalette({name:'Elsa'},{name:'Elsa'}));});

test('grove placement keeps canopy trunks apart and thresholds clear',async()=>{const {scenicTreeSites}=await import('../scenic-trees.js');const scene={width:18,height:18,floor:Array.from({length:18},(_,y)=>Array.from({length:18},(_,x)=>x%4===0||y%4===0?'#':'.').join('')),doors:[{xy:[4,4]}],objects:[]};const p=scenicTreeSites(scene);assert.deepEqual(p,scenicTreeSites(scene));for(let i=0;i<p.length;i++){assert.ok(Math.hypot(p[i].x-.5-4,p[i].y-1-4)>=2.6);for(let j=i+1;j<p.length;j++)assert.ok(Math.hypot(p[i].x-p[j].x,p[i].y-p[j].y)>=3.5);}});
